package co.edu.uniremington.library.service.mapper;

import co.edu.uniremington.library.domain.model.Book;
import co.edu.uniremington.library.service.dto.BookRequest;
import co.edu.uniremington.library.service.dto.BookResponse;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.stream.Collectors;

/**
 * Mapper for Book entity and DTOs.
 */
@Component
public class BookMapper {

    /**
     * Converts BookRequest DTO to Book entity.
     *
     * @param request DTO from client
     * @return Book entity (without ID, as it's generated by database)
     */
    public Book toEntity(BookRequest request) {
        if (request == null) {
            return null;
        }

        Book book = new Book();
        book.setTitle(request.getTitle());
        book.setAuthor(request.getAuthor());
        book.setIsbn(request.getIsbn());
        book.setTotalCopies(request.getTotalCopies());
        book.setAvailableCopies(request.getAvailableCopies());

        return book;
    }

    /**
     * Converts Book entity to BookResponse DTO.
     *
     * @param book Entity from database
     * @return DTO for client
     */
    public BookResponse toResponse(Book book) {
        if (book == null) {
            return null;
        }

        BookResponse response = new BookResponse();
        response.setId(book.getId());
        response.setTitle(book.getTitle());
        response.setAuthor(book.getAuthor());
        response.setIsbn(book.getIsbn());
        response.setTotalCopies(book.getTotalCopies());
        response.setAvailableCopies(book.getAvailableCopies());

        return response;
    }

    /**
     * Converts a list of Book entities to BookResponse DTOs.
     *
     * @param books List of entities
     * @return List of DTOs
     */
    public List<BookResponse> toResponseList(List<Book> books) {
        if (books == null) {
            return null;
        }

        return books.stream()
                .map(this::toResponse)
                .collect(Collectors.toList());
    }

    /**
     * Updates an existing Book entity with data from BookRequest.
     *
     * @param book    Existing entity from database
     * @param request Updated data from client
     */
    public void updateEntityFromRequest(Book book, BookRequest request) {
        if (book == null || request == null) {
            return;
        }

        // Update only the fields that can be changed
        if (request.getTitle() != null) {
            book.setTitle(request.getTitle());
        }
        if (request.getAuthor() != null) {
            book.setAuthor(request.getAuthor());
        }
        if (request.getIsbn() != null) {
            book.setIsbn(request.getIsbn());
        }
        if (request.getTotalCopies() != null) {
            book.setTotalCopies(request.getTotalCopies());
        }
        if (request.getAvailableCopies() != null) {
            book.setAvailableCopies(request.getAvailableCopies());
        }

        // NOTE: We do NOT update ID - it's immutable!
    }
}